package dev.eugheist.ttmodern;
final class IchorPouchWorldClientAudit {
 static boolean saved,checked;static int selected;static net.minecraft.world.item.ItemStack held,ninth;static java.util.List<net.minecraft.world.item.ItemStack> inventory;
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.closeContainer();for(int i=0;i<inventory.size();i++)p.getInventory().setItem(i,inventory.get(i));p.getInventory().selected=selected;p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(selected));p.inventoryMenu.broadcastChanges();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int t){
  if(t==1180)mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());selected=p.getInventory().selected;inventory=new java.util.ArrayList<>();for(int i=0;i<p.getInventory().getContainerSize();i++)inventory.add(p.getInventory().getItem(i).copy());saved=true;for(int i=0;i<36;i++)p.getInventory().setItem(i,net.minecraft.world.item.ItemStack.EMPTY);var pouch=new net.minecraft.world.item.ItemStack(IchorPouch.ITEM.get());var items=IchorPouch.contents(pouch);items.set(116,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND,3));IchorPouch.store(pouch,items);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,pouch);p.getInventory().setItem(9,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.COAL,64));p.inventoryMenu.broadcastChanges();}).join();
  if(t==1190){EnchanterClientAudit.check(mc.player.getMainHandItem().is(IchorPouch.ITEM.get()),"pouch holder inventory packet");mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(t==1200){EnchanterClientAudit.check(mc.screen instanceof IchorPouchScreen&&mc.player.containerMenu instanceof IchorPouchMenu,"actual pouch use opens registered native screen");var menu=mc.player.containerMenu;EnchanterClientAudit.check(menu.slots.get(116).getItem().getCount()==3,"117th slot synchronized on open");mc.gameMode.handleInventoryMouseClick(menu.containerId,117,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);}
  if(t==1210){var menu=mc.player.containerMenu;EnchanterClientAudit.check(menu.slots.get(0).getItem().is(net.minecraft.world.item.Items.COAL)&&menu.slots.get(0).getItem().getCount()==64&&menu.slots.get(117).getItem().isEmpty(),"shift deposit packet synchronized64 ordinary items");mc.gameMode.handleInventoryMouseClick(menu.containerId,116,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);}
  if(t==1220){var menu=mc.player.containerMenu;EnchanterClientAudit.check(menu.slots.get(116).getItem().isEmpty()&&mc.player.getInventory().items.stream().filter(s->s.is(net.minecraft.world.item.Items.DIAMOND)).mapToInt(net.minecraft.world.item.ItemStack::getCount).sum()==3,"117th slot shift withdrawal packet conserves3 diamonds");mc.player.closeContainer();}
  if(t==1230)mc.getSingleplayerServer().submit(()->{try{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());var pouch=p.getMainHandItem();EnchanterClientAudit.check(IchorPouch.contents(pouch).getFirst().getCount()==64&&IchorPouch.contents(pouch).get(116).isEmpty(),"authoritative pouch persisted after native close packet");checked=true;System.out.println("TT ICHOR POUCH WORLD CLIENT AUDIT: ALL PASS (actual use/screen/open117slot sync,shift deposit/withdraw packets,conservation,close persistence,restored inventory)");}finally{restore(mc);}}).join();
 }
}
